module tb_self_check;

    parameter CLK_PERIOD = 10;
    parameter WATCHDOG_TIMEOUT = 25000;

    reg clk;
    reg [7:0] in;
    wire [3:0] out;

    TopModule dut (
        .in(in),
        .out(out)
    );

    integer errors = 0;
    integer checks = 0;

    initial begin
        // Initialize signals
        clk = 0;
        in = 0;

        // Watchdog timer
        #WATCHDOG_TIMEOUT $display("TB_FAILURE: Watchdog timeout");
        $finish;
    end

    always #(CLK_PERIOD/2) clk = ~clk;

    initial begin
        // Phase 1: Reset Check
        @(posedge clk) begin
            in = 8'b0;
            #1;
            if (out !== 4'b0) begin
                $display("TB_FAILURE: Reset Check failed at time %0t: DUT=%h, EXP=%h", $time, out, 4'b0);
                errors++;
            end else begin
                checks++;
            end
        end

        // Phase 2: Deassertion
        @(posedge clk) begin
            in = 8'b0;
            #1;
            if (out !== 4'b0) begin
                $display("TB_FAILURE: Deassertion failed at time %0t: DUT=%h, EXP=%h", $time, out, 4'b0);
                errors++;
            end else begin
                checks++;
            end
        end

        // Phase 3: Directed & Adversarial
        @(posedge clk) begin
            in = 8'b00000000;
            #1;
            if (out !== 4'b0) begin
                $display("TB_FAILURE: All 0s failed at time %0t: DUT=%h, EXP=%h", $time, out, 4'b0);
                errors++;
            end else begin
                checks++;
            end
        end

        @(posedge clk) begin
            in = 8'b10101010;
            #1;
            if (out !== 4'b1010) begin
                $display("TB_FAILURE: 10101010 failed at time %0t: DUT=%h, EXP=%h", $time, out, 4'b1010);
                errors++;
            end else begin
                checks++;
            end
        end

        @(posedge clk) begin
            in = 8'b11111111;
            #1;
            if (out !== 4'b1111) begin
                $display("TB_FAILURE: All 1s failed at time %0t: DUT=%h, EXP=%h", $time, out, 4'b1111);
                errors++;
            end else begin
                checks++;
            end
        end

        @(posedge clk) begin
            in = 8'b01010101;
            #1;
            if (out !== 4'b1010) begin
                $display("TB_FAILURE: 01010101 failed at time %0t: DUT=%h, EXP=%h", $time, out, 4'b1010);
                errors++;
            end else begin
                checks++;
            end
        end

        @(posedge clk) begin
            in = 8'b00001111;
            #1;
            if (out !== 4'b0111) begin
                $display("TB_FAILURE: 00001111 failed at time %0t: DUT=%h, EXP=%h", $time, out, 4'b0111);
                errors++;
            end else begin
                checks++;
            end
        end

        // Phase 4: Randomized Fuzzing
        repeat (40) begin
            @(posedge clk) begin
                in = $urandom;
                #1;
                if (out !== $countones(in)) begin
                    $display("TB_FAILURE: Randomized input failed at time %0t: DUT=%h, EXP=%h", $time, out, $countones(in));
                    errors++;
                end else begin
                    checks++;
                end
            end
        end

        // Finish and report results
        $display("TB_RESULT checks=%0d errors=%0d", checks, errors);
        $finish;
    end

endmodule
