module TopModule (
    input  clk,
    input  reset,
    input  in,
    output detected
);

    reg [3:0] shift_reg;
    reg detected_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 4'b0000;
            detected_reg <= 1'b0;
        end else begin
            shift_reg <= {shift_reg[2:0], in};
            if (shift_reg == 4'b1101)
                detected_reg <= 1'b1;
            else
                detected_reg <= 1'b0;
        end
    end

    assign detected = detected_reg;

endmodule

module tb_self_check;

    parameter CLK_PERIOD = 10;
    parameter WATCHDOG_TIMEOUT = 25000;

    reg clk;
    reg reset;
    reg in;
    wire detected;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .detected(detected)
    );

    integer errors = 0;
    integer checks = 0;

    initial begin
        $timeformat(-9, 2, "ps", 10);
        $display("Starting self-check testbench for TopModule");

        // Initialize signals
        clk = 0;
        reset = 1;
        in = 0;

        // Phase 1: Reset Check
        #30 reset = 0;
        @(posedge clk);
        if (detected !== 1'b0) begin
            $display("TB_FAILURE: Reset check failed");
            errors++;
        end else begin
            checks++;
        end

        // Phase 2: Deassertion
        @(posedge clk);
        if (detected !== 1'b0) begin
            $display("TB_FAILURE: Deassertion check failed");
            errors++;
        end else begin
            checks++;
        end

        // Phase 3: Directed & Adversarial
        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 0;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        if (detected !== 1'b1) begin
            $display("TB_FAILURE: Sequence 1101 detected failed");
            errors++;
        end else begin
            checks++;
        end

        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 0;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        if (detected !== 1'b1) begin
            $display("TB_FAILURE: Sequence 1101 detected failed");
            errors++;
        end else begin
            checks++;
        end

        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 0;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 0;
        @(posedge clk);
        if (detected !== 1'b0) begin
            $display("TB_FAILURE: Sequence 1101 not detected failed");
            errors++;
        end else begin
            checks++;
        end

        @(posedge clk);
        reset = 1;
        @(posedge clk);
        reset = 0;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        in = 0;
        @(posedge clk);
        in = 1;
        @(posedge clk);
        if (detected !== 1'b1) begin
            $display("TB_FAILURE: Sequence 1101 detected after reset failed");
            errors++;
        end else begin
            checks++;
        end

        // Phase 4: Randomized Fuzzing
        repeat (40) begin
            @(posedge clk);
            in = $urandom % 2;
        end

        // Watchdog timeout
        #WATCHDOG_TIMEOUT;
        $display("TB_FAILURE: Watchdog timeout");
        $finish;

        // Final results
        $display("TB_RESULT checks=%0d errors=%0d", checks, errors);
        $finish;
    end

