module TopModule (
    input clk,
    input reset,
    input load,
    input [3:0] value,
    input up,
    input down,
    output reg [3:0] y
);
    reg [3:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
        end else if (load) begin
            counter <= value;
        end else if (up && counter < 15) begin
            counter <= counter + 1;
        end else if (down && counter > 0) begin
            counter <= counter - 1;
        end else begin
            counter <= counter;
        end
    end

    always @(*) begin
        if (reset) begin
            y <= 4'b0000;
        end else if (load) begin
            y <= value;
        end else if (up && counter < 15) begin
            y <= counter + 1;
        end else if (down && counter > 0) begin
            y <= counter - 1;
        end else begin
            y <= counter;
        end
    end
endmodule

