module TopModule (
    input wire clk,
    input wire reset,
    input wire din,
    output reg pulse
);

    reg [2:0] shift_reg;
    reg [1:0] state;
    parameter IDLE = 2'b00, DETECTING = 2'b01, PULSE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 3'b000;
            state <= IDLE;
            pulse <= 0;
        end else begin
            shift_reg <= {shift_reg[1:0], din};
            case (state)
                IDLE: begin
                    if (shift_reg == 3'b011) begin
                        state <= DETECTING;
                    end
                end
                DETECTING: begin
                    if (shift_reg == 3'b011) begin
                        state <= DETECTING;
                    end else begin
                        state <= PULSE;
                    end
                end
                PULSE: begin
                    pulse <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

