module TopModule(input clk, input reset, input din, output reg pulse);
  reg [1:0] state;
  reg [1:0] next_state;
  reg [1:0] bit_buffer;
  integer bit_count;

  parameter IDLE = 2'b00;
  parameter DETECT_0 = 2'b01;
  parameter DETECT_1 = 2'b10;
  parameter DETECT_2 = 2'b11;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      bit_buffer <= 2'b00;
      bit_count <= 0;
      pulse <= 0;
    end else begin
      state <= next_state;
      bit_buffer <= {bit_buffer[0], din};
      if (state == DETECT_2 && din == 1'b0) begin
        pulse <= 1;
      end else begin
        pulse <= 0;
      end
    end
  end

  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (din == 1'b0) begin
          next_state = DETECT_0;
          bit_count = 1;
        end
      end
      DETECT_0: begin
        if (din == 1'b1) begin
          next_state = DETECT_1;
          bit_count = 2;
        end else begin
          next_state = IDLE;
          bit_count = 0;
        end
      end
      DETECT_1: begin
        if (din == 1'b1) begin
          next_state = DETECT_2;
          bit_count = 3;
        end else begin
          next_state = IDLE;
          bit_count = 0;
        end
      end
      DETECT_2: begin
        if (din == 1'b0) begin
          next_state = IDLE;
          bit_count = 0;
        end else begin
          next_state = DETECT_0;
          bit_count = 1;
        end
      end
    endcase
  end

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      bit_count <= 0;
    end else begin
      if (bit_count == 3) begin
        bit_count <= 0;
      end else begin
        bit_count <= bit_count + 1;
      end
    end
  end
endmodule

