module TopModule(input clk, input reset, input din, output reg pulse);
  reg [6:0] shift_reg;
  reg [2:0] state;
  parameter [2:0] IDLE = 3'b000, DETECTING = 3'b001, MATCHED = 3'b010;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      shift_reg <= 7'b0;
      state <= IDLE;
      pulse <= 0;
    end else begin
      shift_reg <= {shift_reg[5:0], din};
      case (state)
        IDLE: begin
          if (shift_reg == 7'b0000000) begin
            state <= DETECTING;
          end
        end
        DETECTING: begin
          if (shift_reg == 7'b1001001) begin
            state <= MATCHED;
          end else if (shift_reg[6] == 1'b1) begin
            state <= IDLE;
          end
        end
        MATCHED: begin
          pulse <= 1;
          state <= IDLE;
        end
      endcase
    end
  end
endmodule

module TopModule (
    input [7:0] in,
    output reg [3:0] out
);
    always @(*) begin
        out = 4'b0000;
        for (integer i = 0; i < 8; i = i + 1) begin
            out = out + in[i];
        end
    end
endmodule

