module tb_self_check;

    parameter CLK_PERIOD = 10;
    parameter WATCHDOG_TIMEOUT = 25000;

    reg clk;
    reg reset;
    reg in;
    wire detected;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .detected(detected)
    );

    integer errors = 0;
    integer checks = 0;

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        in = 0;

        // Watchdog timer
        #WATCHDOG_TIMEOUT $display("TB_FAILURE: Watchdog timeout");
        $finish;

        // Phase 1: Reset Check
        @(posedge clk);
        @(posedge clk);
        @(posedge clk);
        if (detected !== 1'b0) begin
            $display("TB_FAILURE: Reset check failed");
            errors++;
        end
        checks++;

        // Phase 2: Deassertion
        reset = 0;
        @(posedge clk);
        if (detected !== 1'b0) begin
            $display("TB_FAILURE: Deassertion check failed");
            errors++;
        end
        checks++;

        // Phase 3: Directed & Adversarial
        test_sequence("00001101", "00000001");
        test_sequence("1101101", "00000011");
        test_sequence("11001101", "00000001");
        test_sequence("11010000", "00000000");
        test_sequence("11011101", "00000011");

        // Phase 4: Randomized Fuzzing
        repeat (40) begin
            in = $urandom;
            @(posedge clk);
        end

        // Final report
        $display("TB_RESULT checks=%0d errors=%0d", checks, errors);
        $finish;
    end

    task test_sequence(input string input_vector, input string expected_output);
        integer i;
        for (i = 0; i < input_vector.len(); i++) begin
            in = input_vector[i] == '1';
            @(posedge clk);
            if (detected !== expected_output[i] == '1') begin
                $display("TB_FAILURE: Mismatch at time %0t: DUT=%h, EXP=%h", $time, detected, expected_output[i]);
                errors++;
            end
            checks++;
        end
    endtask

    always #CLK_PERIOD / 2 clk = ~clk;

endmodule
