module TopModule (
    input clk,
    input reset,
    input load,
    input [7:0] data,
    output reg [7:0] q
);
    reg [7:0] sr;
    reg [7:0] feedback;
    reg [2:0] state, next_state;

    // State definitions
    parameter IDLE = 3'b000, RESET = 3'b001, LOAD = 3'b010, SHIFT = 3'b011;

    // State register update with reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= RESET;
        end else begin
            state <= next_state;
        end
    end

    // Combinational next_state logic with default assignment and default case
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (reset) begin
                    next_state = RESET;
                end else if (load) begin
                    next_state = LOAD;
                end else begin
                    next_state = SHIFT;
                end
            end
            RESET: begin
                if (reset == 0) begin
                    next_state = IDLE;
                end
            end
            LOAD: begin
                if (reset || load == 0) begin
                    next_state = IDLE;
                end
            end
            SHIFT: begin
                if (reset || load) begin
                    next_state = IDLE;
                end
            end
            default: next_state = IDLE;
        endcase
    end

    // Registered or clean combinational output
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 8'h01;
        end else begin
            case (state)
                IDLE: begin
                    if (load) begin
                        q <= data;
                    end
                end
                SHIFT: begin
                    feedback = sr[7] ^ sr[5] ^ sr[4] ^ sr[3];
                    q <= {sr[6:0], feedback};
                end
                default: q <= q;
            endcase
        end
    end

    // Shift register logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sr <= 8'h01;
        end else if (state == SHIFT) begin
            sr <= {sr[6:0], feedback};
        end
    end
endmodule

